<?php
$header=is_array($document['header']??null)?$document['header']:[];
$summary=is_array($document['summary']??null)?$document['summary']:[];
$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$sections=['gross_sales'=>'Gross Sales','item_totals'=>'Item Totals','waiter_totals'=>'Waiter Totals','returns'=>'Returns','voids'=>'Voids','changes'=>'Changes','requisitions'=>'Requisitions','units_generated'=>'Units Generated','transfers'=>'Transfers','recipe_consumption'=>'Recipe / Raw-material Consumption','cancelled_orders'=>'Cancelled / Abandoned Orders'];
?><!doctype html><html><head><meta charset="utf-8"><title>CSP</title><style>@page{size:80mm auto;margin:0}*{box-sizing:border-box}body{width:79mm;margin:0;font:11px Arial;color:#000}.csp{padding:2mm}.center{text-align:center}.stars{white-space:nowrap;overflow:hidden;font-weight:bold}h1{font-size:18px;margin:2px 0}h2{font-size:13px;border-bottom:1px solid #000;margin:5px 0 2px;padding-bottom:2px}table{width:100%;border-collapse:collapse}td,th{padding:2px 1px;text-align:left;border-bottom:1px dotted #777}td:last-child,th:last-child{text-align:right}.meta{display:flex;justify-content:space-between}</style></head><body><main class="csp"><header class="center"><div class="stars">***********************************************************</div><h1><?= $esc($header['counter_name']??'') ?> CSP</h1><div><?= $esc($header['company_name']??'') ?></div><div>SHIFT: <?= $esc($header['shift']??$header['shift_date']??'') ?></div><div><?= $esc($header['print_time']??'') ?></div><div class="stars">***********************************************************</div></header><?php foreach($sections as $key=>$label): $rows=$document[$key]??($summary[$key]??null); if(is_numeric($rows)||is_string($rows)){ $rows=[['name'=>$label,'value'=>$rows]]; } if(!is_array($rows)||!$rows)continue; ?><section><h2><?= $esc($label) ?></h2><table><?php foreach($rows as $row): if(!is_array($row))$row=['name'=>$label,'value'=>$row]; $name=$row['name']??$row['item_name']??$row['waiter']??$row['description']??''; $value=$row['value']??$row['qty']??$row['amount']??$row['total']??''; ?><tr><td><?= $esc($name) ?></td><td><?= $esc($value) ?></td></tr><?php endforeach; ?></table></section><?php endforeach; ?><footer class="center"><div class="stars">***********************************************************</div>END OF COUNTER SUMMARY</footer></main></body></html>
